export const WHITE_PRODUCTS: WhiteProduct[] = [
  {key: 1, slug: 'lnyanoy-kostyum-s-yubkoy-maksi', en: 'Linen Maxi Suit', ru: 'Льняной костюм с юбкой макси', cat: 'tailoring', price: 4269, descEn: 'A sleeveless linen vest and a floor-skimming maxi skirt, cut for summer ease. Natural buttons, a defined waist, unlined.', descRu: 'Льняной жилет без рукавов и юбка макси в пол — летняя лёгкость. Натуральные пуговицы, подчёркнутая талия, без подклада.', storyEn: 'A two-piece that holds its shape through the day and stops asking to be pressed after the first hour. The sleeveless vest is cut close — darts draw the waist in, natural buttons meet edge to edge, the armhole is open enough to take a tee underneath or nothing at all. The maxi skirt falls from the hip in a clean wedge, long enough to cover the ankle with the stride left free. The linen is a heavier weave with visible texture: it does not go sheer in sunlight and keeps its colour through washing. Unlined, so it stays breathable in heat. Wear it whole, or apart — the vest sits on jeans, the skirt takes any top.', storyRu: 'Костюм из двух частей, который держит форму весь день и не просит глажки после первого часа. Жилет без рукавов скроен по фигуре: вытачки собирают талию, натуральные пуговицы застёгиваются встык, пройма открытая — под него легко уходит футболка или ничего. Юбка макси падает от бедра ровным клином, длина закрывает щиколотку, шаг свободный. Лён взят плотный, с характерной фактурой: он не просвечивает на солнце и держит цвет после стирки. Без подклада — костюм остаётся дышащим в жару. Носится целиком как комплект и по отдельности: жилет садится на джинсы, юбка живёт с любым верхом.', compositionEn: '100% linen', compositionRu: '100% лён', careEn: 'Machine wash cold, gentle', careRu: 'Деликатная стирка в холодной воде', colors: [IVORY, {...BLACK, image: '/images/white/products/p-1008989269-black.jpg', gallery: ['/images/white/products/p-1008989269-black-b.jpg', '/images/white/products/p-1008989269-black-d.jpg', '/images/white/products/p-1008989269-black-s.jpg', '/images/white/products/p-1008989269-black-m.jpg']}, {...SKYBLUE, image: '/images/white/products/p-1008989269-blue.jpg', gallery: ['/images/white/products/p-1008989269-blue-b.jpg', '/images/white/products/p-1008989269-blue-d.jpg', '/images/white/products/p-1008989269-blue-s.jpg', '/images/white/products/p-1008989269-blue-m.jpg']}, {...YELLOW, image: '/images/white/products/p-1008989269-yellow.jpg', gallery: ['/images/white/products/p-1008989269-yellow-b.jpg', '/images/white/products/p-1008989269-yellow-d.jpg', '/images/white/products/p-1008989269-yellow-s.jpg', '/images/white/products/p-1008989269-yellow-m.jpg']}, {...GREEN, image: '/images/white/products/p-1008989269-green.jpg', gallery: ['/images/white/products/p-1008989269-green-b.jpg', '/images/white/products/p-1008989269-green-d.jpg', '/images/white/products/p-1008989269-green-s.jpg', '/images/white/products/p-1008989269-green-m.jpg']}, {...ORANGE, image: '/images/white/products/p-1008989269-orange.jpg', gallery: ['/images/white/products/p-1008989269-orange-b.jpg', '/images/white/products/p-1008989269-orange-d.jpg', '/images/white/products/p-1008989269-orange-s.jpg', '/images/white/products/p-1008989269-orange-m.jpg']}, {...ROSE, image: '/images/white/products/p-1008989269-rose.jpg', gallery: ['/images/white/products/p-1008989269-rose-b.jpg', '/images/white/products/p-1008989269-rose-d.jpg', '/images/white/products/p-1008989269-rose-s.jpg', '/images/white/products/p-1008989269-rose-m.jpg']}, {...BROWN, image: '/images/white/products/p-1008989269-brown.jpg', gallery: ['/images/white/products/p-1008989269-brown-b.jpg', '/images/white/products/p-1008989269-brown-d.jpg', '/images/white/products/p-1008989269-brown-s.jpg', '/images/white/products/p-1008989269-brown-m.jpg']}], image: '/images/white/products/p-1008989269.jpg', nm: 1008989269, gallery: ['/images/white/products/p-1008989269-3.jpg', '/images/white/products/p-1008989269-4.jpg', '/images/white/products/p-1008989269-5.jpg', '/images/white/products/p-1008989269-6.jpg', '/images/white/products/p-1008989269-7.jpg']},
  {key: 2, slug: 'palto-pidzhak-pritalennoe', en: 'Fitted Blazer Coat', ru: 'Пальто-пиджак приталенное', cat: 'outerwear', price: 34900, descEn: 'A demi-season coat cut like a blazer — clean collarless shoulders and a sculpted, buttoned waist. Fully lined.', descRu: 'Демисезонное пальто с кроем пиджака — чистые плечи без воротника и скульптурная талия на пуговицах. На подкладе.', storyEn: 'A demi-season coat built on blazer logic: a clean shoulder, no collar, an open neckline. The waist is drawn in and buttoned, so the silhouette sculpts rather than falls straight. It ends mid-thigh with a full sleeve. The wool blend keeps its shape on the hanger and does not crease at the elbow after a day in the car. Fully lined — it goes over a sweater without fighting you and comes off in one motion. A coat for the city between +5 and +15: fine knitwear or a shirt underneath, nothing needed on top.', storyRu: 'Демисезонное пальто, скроенное по логике пиджака: плечо чистое, без воротника, линия горловины открытая. Талия собрана и застёгнута на пуговицы — силуэт получается скульптурный, а не прямой. Длина до середины бедра, рукав полный. Шерстяная смесь держит форму на весу и не мнётся в рукаве после дня в машине. Полностью на подкладе: надевается поверх свитера без сопротивления, снимается одним движением. Это пальто для города в +5…+15 — под него уходит и тонкий трикотаж, и рубашка, а сверху ничего не нужно.', compositionEn: 'Wool blend', compositionRu: 'Шерстяная смесь', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [SAND, {...CHARCOAL, image: '/images/white/products/p-795522033-charcoal.jpg', gallery: ['/images/white/products/p-795522033-charcoal-b.jpg', '/images/white/products/p-795522033-charcoal-d.jpg', '/images/white/products/p-795522033-charcoal-s.jpg', '/images/white/products/p-795522033-charcoal-m.jpg']}], image: '/images/white/products/p-795522033.jpg', nm: 795522033, gallery: ['/images/white/products/p-795522033-2.jpg', '/images/white/products/p-795522033-3.jpg', '/images/white/products/p-795522033-4.jpg', '/images/white/products/p-795522033-5.jpg', '/images/white/products/p-795522033-6.jpg']},
  {key: 3, slug: 'zhilet-kostyumnyy-s-baskoy', en: 'Peplum Suit Vest', ru: 'Жилет костюмный с баской', cat: 'tailoring', price: 4466, descEn: 'A classic tailored vest with a peplum flare and a buttoned front. Nipped at the waist, sharp over anything.', descRu: 'Классический костюмный жилет с баской и застёжкой на пуговицы. Приталенный, острый поверх чего угодно.', storyEn: 'A tailored vest where the work sits in the cut rather than the trim. The peplum leaves the waist in a soft wave and covers the hip, so the line reads as an hourglass even over straight trousers. The front buttons through, the back is whole, the armhole is high — it does not ride up when you raise your arms. A dense cotton blend with a matte surface that holds a sharp edge. Wear it as a top in its own right: matching trousers make it a suit, jeans make it a contrast, over a shirt it reads as the third piece.', storyRu: 'Классический костюмный жилет, у которого работа сделана в крое, а не в отделке. Баска отходит от талии мягкой волной и прикрывает бедро — силуэт читается как песочные часы даже поверх прямых брюк. Перед застёгивается на пуговицы, спина цельная, пройма высокая: жилет не съезжает, когда поднимаешь руки. Хлопковая смесь плотная, с матовой поверхностью, держит острые линии. Носится как самостоятельный верх — с брюками в тон получается костюм, с джинсами выходит контраст, поверх рубашки читается как жилет от тройки.', compositionEn: 'Cotton blend', compositionRu: 'Хлопковая смесь', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [{...BROWN}, {...BLACK, image: '/images/white/products/p-962827637-black.jpg', gallery: ['/images/white/products/p-962827637-black-b.jpg', '/images/white/products/p-962827637-black-d.jpg', '/images/white/products/p-962827637-black-s.jpg', '/images/white/products/p-962827637-black-m.jpg']}], image: '/images/white/products/p-962827637.jpg', nm: 962827637, gallery: ['/images/white/products/p-962827637-3.jpg', '/images/white/products/p-962827637-4.jpg', '/images/white/products/p-962827637-5.jpg', '/images/white/products/p-962827637-6.jpg', '/images/white/products/p-962827637-7.jpg']},
  {key: 4, slug: 'svitshot-s-bantikami', en: 'Bow Sweatshirt', ru: 'Свитшот с бантиками', cat: 'knitwear', price: 8000, descEn: 'An oversized cotton sweatshirt softened with bow details. Dropped shoulders, ribbed trims, soft cotton.', descRu: 'Оверсайз-свитшот из хлопка, смягчённый бантиками. Приспущенное плечо, рубчатые края, мягкий хлопок.', storyEn: 'A relaxed sweatshirt softened with bows along the sleeve. The shoulder is dropped and the volume is there, but it does not drag: ribbed cuffs and hem gather the shape and keep it from spreading after washing. A cotton blend with a soft inside face — it goes on bare skin without scratching. It covers the waistband, which is why it sits equally well with a balloon skirt, straight jeans or high-rise trousers. The bows are stitched by hand and do not catch under a coat.', storyRu: 'Свитшот свободного кроя, смягчённый бантиками по линии рукава. Плечо приспущено, объём есть, но он не тянет вниз: рубчатые манжеты и низ собирают форму и не дают вещи расползтись после стирки. Хлопковая смесь с мягкой изнанкой — надевается на голое тело без раздражения. Длина закрывает пояс, поэтому свитшот одинаково живёт с юбкой-баллон, прямыми джинсами и брюками с высокой посадкой. Бантики пришиты вручную и не мешают надевать пальто сверху.', compositionEn: 'Cotton blend', compositionRu: 'Хлопковая смесь', careEn: 'Machine wash cold', careRu: 'Машинная стирка в холодной воде', colors: [GREY, {...BLACK, image: '/images/white/products/p-442577291-black.jpg', gallery: ['/images/white/products/p-442577291-black-b.jpg', '/images/white/products/p-442577291-black-d.jpg', '/images/white/products/p-442577291-black-s.jpg', '/images/white/products/p-442577291-black-m.jpg']}], image: '/images/white/products/p-442577291.jpg', nm: 442577291, gallery: ['/images/white/products/p-442577291-2.jpg', '/images/white/products/p-442577291-3.jpg', '/images/white/products/p-442577291-4.jpg', '/images/white/products/p-442577291-b.jpg']},
  {key: 5, slug: 'yubka-karandash-s-kruzhevnym-podyubnikom', en: 'Lace-Hem Pencil Skirt', ru: 'Юбка карандаш с кружевным подъюбником', cat: 'skirts', price: 25000, season: 'aw26', descEn: 'A long pencil skirt with a lace underskirt showing at the hem. Office discipline, with one thing left undone.', descRu: 'Длинная юбка карандаш с кружевным подъюбником, который выходит из-под низа. Офисная дисциплина с одной незастёгнутой деталью.', storyEn: 'A pencil skirt cut long — the hem falls below the calf, where a shorter one would stop at the knee and ask to be pulled down all day. A wide waistband sits high and holds; the front is flat, the back takes a vent so the stride is not shortened. The lace underskirt is stitched in, not layered on, and shows a hand’s width below the hem: from the front it reads as a finish, from behind as the whole point. The cloth is a dense polyester-viscose with elastane — it holds a crease, does not shine at the seat and gives when you sit down. It takes a shirt tucked in and a knit left out.', storyRu: 'Юбка карандаш удлинённого кроя: низ падает ниже середины голени, тогда как короткая садилась бы на колено и весь день просила бы себя одёрнуть. Широкий пояс стоит высоко и держит, передняя половина идёт гладко, сзади заложена шлица — шаг не укорачивается. Кружевной подъюбник втачан, а не надет сверху, и выходит на ширину ладони из-под низа: спереди читается как отделка, со спины — как весь смысл вещи. Полотно плотное, полиэстер с вискозой и эластаном: держит складку, не лоснится на посадке и тянется, когда садишься. Берёт заправленную рубашку и выпущенный трикотаж.', compositionEn: '55% polyester, 40% viscose, 5% elastane', compositionRu: 'Полиэстер 55%, вискоза 40%, эластан 5%', careEn: 'Machine wash cold, gentle', careRu: 'Деликатная стирка при 30°', colors: [{...BLACK, image: '/images/white/products/p-1217814224-v2-black.jpg', gallery: ['/images/white/products/p-1217814224-v2-black-b.jpg', '/images/white/products/p-1217814224-v2-black-c.jpg', '/images/white/products/p-1217814224-v2-black-d.jpg']}, {...GREY, image: '/images/white/products/p-1217814227-v2-grey.jpg', gallery: ['/images/white/products/p-1217814227-v2-grey-b.jpg', '/images/white/products/p-1217814227-v2-grey-c.jpg', '/images/white/products/p-1217814227-v2-grey-d.jpg']}, {...BROWN, image: '/images/white/products/p-1217805724-v2-brown.jpg', gallery: ['/images/white/products/p-1217805724-v2-brown-b.jpg', '/images/white/products/p-1217805724-v2-brown-c.jpg', '/images/white/products/p-1217805724-v2-brown-d.jpg']}, {...SAND, image: '/images/white/products/p-1217814226-v2-sand.jpg', gallery: ['/images/white/products/p-1217814226-v2-sand-b.jpg', '/images/white/products/p-1217814226-v2-sand-c.jpg', '/images/white/products/p-1217814226-v2-sand-d.jpg']}], image: '/images/white/products/p-1217814224-v2-black.jpg', nm: 1217814224, gallery: ['/images/white/products/p-1217814224-v2-black-b.jpg', '/images/white/products/p-1217814224-v2-black-c.jpg', '/images/white/products/p-1217814224-v2-black-d.jpg']},
  {key: 6, slug: 'korset-vecherniy-s-baskoy', en: 'Peplum Evening Corset', ru: 'Корсет вечерний с баской', cat: 'dresses', price: 2932, descEn: 'A structured evening corset with a peplum hem. A boned bodice and a defined waist, made to be dressed up.', descRu: 'Структурный вечерний корсет с баской. Лиф на косточках и чёткая талия — создан для выхода.', storyEn: 'An evening corset with real structure: the boned bodice keeps the back straight and marks the waist, and the peplum spreads softly from it to cover the join with a skirt or trousers. The top edge is straight and strapless, leaving the shoulder line open. A dense cotton blend with no stretch, so the silhouette does not drift by the end of the night. It fastens at the back. This is a going-out top: a satin balloon skirt makes it evening, straight trousers make it dinner, and it disappears under a coat worn over the shoulders.', storyRu: 'Вечерний корсет со структурой: лиф на косточках держит спину прямо и очерчивает талию, баска мягко расходится от неё и прикрывает переход к юбке или брюкам. Верх ровный, без бретелей — линия плеча остаётся открытой. Хлопковая смесь плотная, не тянется, поэтому силуэт не плывёт к концу вечера. Застёжка сзади. Это верх для выхода: с атласной юбкой-баллон получается вечерний комплект, с прямыми брюками — костюм для ужина, под пальто на плечах уходит целиком.', compositionEn: 'Cotton blend', compositionRu: 'Хлопковая смесь', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [BLACK, {...SAND, image: '/images/white/products/p-675104410-beige.jpg', gallery: ['/images/white/products/p-675104410-beige-b.jpg', '/images/white/products/p-675104410-beige-d.jpg', '/images/white/products/p-675104410-beige-s.jpg', '/images/white/products/p-675104410-beige-m.jpg']}, {...BROWN, image: '/images/white/products/p-675104410-brown.jpg', gallery: ['/images/white/products/p-675104410-brown-b.jpg', '/images/white/products/p-675104410-brown-d.jpg', '/images/white/products/p-675104410-brown-s.jpg', '/images/white/products/p-675104410-brown-m.jpg']}], image: '/images/white/products/p-675104410.jpg', nm: 675104410, gallery: ['/images/white/products/p-675104410-3.jpg', '/images/white/products/p-675104410-4.jpg', '/images/white/products/p-675104410-b.jpg', '/images/white/products/p-675104410-d.jpg']},
  {key: 7, slug: 'bryuki-alladiny', en: 'Draped Harem Trousers', ru: 'Брюки алладины', cat: 'tailoring', price: 2927, descEn: 'Softly draped harem trousers with a relaxed fall and a clean waist. Easy tailoring for every day.', descRu: 'Мягко драпированные брюки алладины со свободным силуэтом и чистой талией. Лёгкий тайлоринг на каждый день.', storyEn: 'Harem trousers with a soft drape: the cloth gathers at the waist, falls in large folds and narrows towards the ankle. The rise is high and the waistband elastic — they sit on the body with no buttons or zips and do not press after a meal. The viscose blend is weighty in the hand, so the folds lie rather than stick out. They end at the ankle bone, ready for trainers, courts or sandals. Everyday trousers that read as evening ones: a vest makes them tailoring, a t-shirt makes them rest.', storyRu: 'Брюки алладины с мягкой драпировкой: ткань собирается на поясе и уходит вниз крупными складками, а к щиколотке силуэт сужается. Посадка высокая, пояс эластичный — брюки садятся по фигуре без пуговиц и молний и не давят после еды. Вискозная смесь тяжёлая на ощупь, поэтому складки лежат, а не топорщатся. Длина до косточки: под кроссовки, лодочки и босоножки. Это брюки на каждый день, которые выглядят как вечерние — с жилетом получается тайлоринг, с футболкой отдых.', compositionEn: 'Viscose blend', compositionRu: 'Вискозная смесь', careEn: 'Machine wash cold', careRu: 'Машинная стирка в холодной воде', colors: [SAND, {...BLACK, image: '/images/white/products/p-962783109-black.jpg', gallery: ['/images/white/products/p-962783109-black-b.jpg', '/images/white/products/p-962783109-black-d.jpg', '/images/white/products/p-962783109-black-s.jpg', '/images/white/products/p-962783109-black-m.jpg']}, {...BROWN, image: '/images/white/products/p-962783109-brown.jpg', gallery: ['/images/white/products/p-962783109-brown-b.jpg', '/images/white/products/p-962783109-brown-d.jpg', '/images/white/products/p-962783109-brown-s.jpg', '/images/white/products/p-962783109-brown-m.jpg']}, {...GREEN, image: '/images/white/products/p-962783109-green.jpg', gallery: ['/images/white/products/p-962783109-green-b.jpg', '/images/white/products/p-962783109-green-d.jpg', '/images/white/products/p-962783109-green-m.jpg', '/images/white/products/p-962783109-green-s.jpg']}], image: '/images/white/products/p-962783109.jpg', nm: 962783109, gallery: ['/images/white/products/p-962783109-3.jpg', '/images/white/products/p-962783109-4.jpg', '/images/white/products/p-962783109-b.jpg', '/images/white/products/p-962783109-d.jpg']},
  {key: 8, slug: 'yubka-ballon-atlasnaya', en: 'Satin Balloon Skirt', ru: 'Юбка баллон атласная', cat: 'skirts', price: 2565, descEn: 'A satin balloon mini with built-in shorts and a rounded volume. Matte sheen, holds its volume.', descRu: 'Атласная юбка-баллон мини с шортами и округлым объёмом. Матовый блеск, форма держит объём.', storyEn: 'A satin balloon skirt with a rounded volume: the hem is gathered inward, so it holds its shape without a petticoat. Shorts are built in — sit down, walk into the wind, stop thinking about the length. High rise, elasticated waistband. The satin is matte with a muted sheen: it catches light along the curve without looking glossy, which is what lets the skirt work in daylight. Mini length. A corset makes it evening, a sweatshirt makes it an ordinary Saturday, opaque tights take it into autumn.', storyRu: 'Атласная юбка-баллон с округлым объёмом: подол собран внутрь, и юбка держит форму сама, без подъюбника. Внутри вшиты шорты — можно садиться, идти по ветру и не думать о длине. Посадка высокая, пояс на резинке. Атлас матовый, с приглушённым блеском: он ловит свет по изгибу, но не выглядит нарядно-глянцевым, поэтому юбка работает и днём. Длина мини. С корсетом получается вечер, со свитшотом — обычная суббота, с плотными колготками уходит в осень.', compositionEn: 'Satin', compositionRu: 'Атлас', careEn: 'Machine wash cold', careRu: 'Машинная стирка в холодной воде', colors: [IVORY, {...BLACK, image: '/images/white/products/p-371980450-black.jpg', gallery: ['/images/white/products/p-371980450-black-b.jpg', '/images/white/products/p-371980450-black-d.jpg', '/images/white/products/p-371980450-black-s.jpg', '/images/white/products/p-371980450-black-m.jpg']}, {...RED, image: '/images/white/products/p-371980450-red.jpg', gallery: ['/images/white/products/p-371980450-red-b.jpg', '/images/white/products/p-371980450-red-d.jpg', '/images/white/products/p-371980450-red-s.jpg', '/images/white/products/p-371980450-red-m.jpg']}], image: '/images/white/products/p-371980450.jpg', nm: 371980450, gallery: ['/images/white/products/p-371980450-d.jpg', '/images/white/products/p-371980450-b.jpg', '/images/white/products/p-371980450-s.jpg']},
  {key: 9, slug: 'rubashka-oversayz-s-kruzhevom', en: 'Lace Oversized Shirt', ru: 'Рубашка оверсайз с кружевом', cat: 'dresses', price: 8326, descEn: 'An oversized shirt with a dramatic gathered sleeve — drawn at the wrist with a drawstring tie, a narrow lace edging showing at the cuff. Relaxed shoulders, a curved shirttail hem.', descRu: 'Оверсайз-рубашка с объёмным рукавом — кулиска с завязками у запястья, узкое кружево по краю манжеты. Свободные плечи, скруглённый низ.', storyEn: 'An oversized shirt with a dramatic sleeve: gathered at the wrist on a drawstring tie, with a narrow lace edging showing below the cuff. The shoulder is dropped, the body is generous, the hem is curved — it tucks in and hangs out equally well. Soft cotton with a lightly crumpled texture that never asks for an iron. Buttons through. Wear it over jeans, over a dress as a light layer, or as a cover-up. The sleeve is the point of this shirt, so anything worn over it is better cut loose.', storyRu: 'Рубашка свободного кроя с драматичным рукавом: у запястья он собран на кулиску с завязками, из-под манжеты выходит узкое кружево. Плечо приспущено, объём по корпусу большой, низ скруглён — рубашка одинаково хорошо заправляется и остаётся навыпуск. Хлопок мягкий, с лёгкой мятой фактурой, которая не требует утюга. Застёжка на пуговицы по всей длине. Носится на джинсы, поверх платья как лёгкий верхний слой и в качестве пляжной накидки. Рукав — главное в этой вещи, поэтому пальто поверх лучше надевать свободное.', compositionEn: 'Cotton with lace trim', compositionRu: 'Хлопок с кружевной отделкой', careEn: 'Hand wash cold', careRu: 'Ручная стирка в холодной воде', colors: [{...BLACK, en: 'Black pinstripe', ru: 'Чёрный в полоску'}, {...SAND, en: 'Vanilla polka dot', ru: 'Ваниль в горошек', image: '/images/white/products/p-1113526969-sand.jpg', gallery: ['/images/white/products/p-1113526969-sand-b.jpg', '/images/white/products/p-1113526969-sand-d.jpg', '/images/white/products/p-1113526969-sand-s.jpg', '/images/white/products/p-1113526969-sand-m.jpg']}, {...GREY, en: 'Grey polka dot', ru: 'Серый в горошек', image: '/images/white/products/p-1113526969-grey.jpg', gallery: ['/images/white/products/p-1113526969-grey-b.jpg', '/images/white/products/p-1113526969-grey-d.jpg', '/images/white/products/p-1113526969-grey-s.jpg', '/images/white/products/p-1113526969-grey-m.jpg']}, {...ROSE, en: 'Rose check', ru: 'Розовая клетка', image: '/images/white/products/p-1113526969-rose.jpg', gallery: ['/images/white/products/p-1113526969-rose-b.jpg', '/images/white/products/p-1113526969-rose-d.jpg', '/images/white/products/p-1113526969-rose-s.jpg', '/images/white/products/p-1113526969-rose-m.jpg']}], image: '/images/white/products/p-1113526969.jpg', nm: 1113526969, gallery: ['/images/white/products/p-1113526969-3.jpg', '/images/white/products/p-1113526969-4.jpg', '/images/white/products/p-1113526969-b.jpg', '/images/white/products/p-1113526969-d.jpg']},
  {key: 10, slug: 'yubka-shorty-zamshevaya', en: 'Suede Skort', ru: 'Юбка-шорты замшевая', cat: 'skirts', price: 2922, descEn: 'A suede mini skort finished with a scalloped lace hem — the ease of shorts under the line of a skirt. Soft hand, elasticated waist.', descRu: 'Замшевая юбка-шорты с кружевной отделкой по низу — лёгкость шорт под линией юбки. Мягкая фактура, эластичный пояс.', storyEn: 'A suede skort: a skirt from the outside, shorts built in underneath — sit, bend, take the stairs without adjusting anything. Scalloped lace runs along the hem and softens the straight suede line. Elasticated waistband, high rise. The faux suede is soft with a velvety surface that keeps its colour and does not stretch across the hip. Mini length, A-line. Opaque tights and tall boots take it into the cold; a t-shirt keeps it summer.', storyRu: 'Замшевая юбка-шорты: снаружи читается как юбка, внутри вшиты шорты — можно садиться, наклоняться и подниматься по лестнице, не поправляя. По низу идёт кружевная отделка с фестонами, она смягчает прямой замшевый силуэт. Пояс на резинке, посадка высокая. Искусственная замша мягкая, с бархатистой поверхностью, которая держит цвет и не тянется на бедре. Длина мини, крой А-силуэт. С плотными колготками и высокими сапогами уходит в холод, с футболкой остаётся летней.', compositionEn: 'Faux suede with lace trim', compositionRu: 'Искусственная замша с кружевом', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [IVORY, {...BROWN, image: '/images/white/products/p-1143078000-brown.jpg', gallery: ['/images/white/products/p-1143078000-brown-b.jpg', '/images/white/products/p-1143078000-brown-d.jpg', '/images/white/products/p-1143078000-brown-s.jpg', '/images/white/products/p-1143078000-brown-m.jpg']}, {...BLACK, image: '/images/white/products/p-1143078000-black.jpg', gallery: ['/images/white/products/p-1143078000-black-b.jpg', '/images/white/products/p-1143078000-black-d.jpg', '/images/white/products/p-1143078000-black-s.jpg', '/images/white/products/p-1143078000-black-m.jpg']}, {...GREEN, image: '/images/white/products/p-1143078000-green.jpg', gallery: ['/images/white/products/p-1143078000-green-b.jpg', '/images/white/products/p-1143078000-green-d.jpg', '/images/white/products/p-1143078000-green-s.jpg', '/images/white/products/p-1143078000-green-m.jpg']}, {...GREY, image: '/images/white/products/p-1143078000-grey.jpg', gallery: ['/images/white/products/p-1143078000-grey-b.jpg', '/images/white/products/p-1143078000-grey-d.jpg', '/images/white/products/p-1143078000-grey-s.jpg', '/images/white/products/p-1143078000-grey-m.jpg']}], image: '/images/white/products/p-1143078000.jpg', nm: 1143078000, gallery: ['/images/white/products/p-1143078000-b.jpg', '/images/white/products/p-1143078000-d.jpg', '/images/white/products/p-1143078000-s.jpg', '/images/white/products/p-1143078000-m.jpg']},
  {key: 11, slug: 'palto-oversayz-s-poyasom', en: 'Long Belted Coat', ru: 'Пальто оверсайз с поясом', cat: 'outerwear', price: 34900, descEn: 'A long oversized demi-season coat with a self-tie belt. Dropped shoulders, a deep collar, floor-skimming.', descRu: 'Длинное оверсайз-пальто демисезона с поясом. Приспущенное плечо, глубокий воротник, длина в пол.', storyEn: 'A long oversized coat with a belt — volume by design rather than by accident. The shoulder is dropped, the collar deep, and the floor-skimming length covers whatever is underneath. Tie the belt and the silhouette gathers at the waist; leave it and the coat reads as a straight robe. Two garments in one. The wool blend is dense, holds warmth and does not let the wind through. Fully lined, with deep pockets. For demi-season and a mild winter: a chunky knit goes under it without any sense of crowding.', storyRu: 'Длинное пальто оверсайз с поясом — тот случай, когда объём задуман, а не случился. Плечо приспущено, воротник глубокий, длина в пол закрывает всё, что надето снизу. Пояс завязывается на талии и собирает силуэт, а без него пальто читается как прямой халат: две вещи в одной. Шерстяная смесь плотная, держит тепло и не продувается на ветру. Полностью на подкладе, карманы глубокие. Демисезон и мягкая зима — под него уходит свитер крупной вязки без чувства тесноты.', compositionEn: 'Wool blend', compositionRu: 'Шерстяная смесь', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [BLACK, {...CAMEL, image: '/images/white/products/p-100797221-camel.jpg', gallery: ['/images/white/products/p-100797221-camel-b.jpg', '/images/white/products/p-100797221-camel-d.jpg', '/images/white/products/p-100797221-camel-s.jpg', '/images/white/products/p-100797221-camel-m.jpg']}, {...BROWN, image: '/images/white/products/p-100797221-brown.jpg', gallery: ['/images/white/products/p-100797221-brown-b.jpg', '/images/white/products/p-100797221-brown-d.jpg', '/images/white/products/p-100797221-brown-s.jpg', '/images/white/products/p-100797221-brown-m.jpg']}], image: '/images/white/products/p-100797221.jpg', nm: 100797221, gallery: ['/images/white/products/p-100797221-2.jpg', '/images/white/products/p-100797221-3.jpg', '/images/white/products/p-100797221-b.jpg', '/images/white/products/p-100797221-d.jpg']},
  {key: 12, slug: 'plate-lapsha-s-razrezom', en: 'Ribbed Slit Dress', ru: 'Платье лапша с разрезом', cat: 'dresses', price: 632, descEn: 'A long ribbed knit dress that skims the body, opened by a single side slit. Second-skin soft.', descRu: 'Длинное платье в рубчик, которое скользит по фигуре, с одним боковым разрезом. Мягкое как вторая кожа.', storyEn: 'A long ribbed dress that skims the body without gripping it. The knit is fine and elastic, and the vertical rib draws the line upward. A single side slit opens the stride and leaves the walk free. Round neck, long sleeve, whole back. The viscose is soft as second skin and does not cling with static. The dress carries itself with sandals, and takes layers well: a vest on top, a coat over it, boots below — and it is a different outfit.', storyRu: 'Длинное платье в рубчик, которое скользит по фигуре и не сдавливает. Вязка тонкая, эластичная, с вертикальным рубчиком — он вытягивает силуэт. Один боковой разрез открывает шаг и делает походку свободной. Горловина круглая, рукав длинный, спина цельная. Вискоза мягкая как вторая кожа и не электризуется. Платье работает само по себе с босоножками и укрупняется слоями: жилет сверху, пальто поверх, ботинки внизу — и это уже другой образ.', compositionEn: 'Ribbed viscose', compositionRu: 'Вискоза в рубчик', careEn: 'Hand wash cold', careRu: 'Ручная стирка в холодной воде', colors: [OAT, {...GREY, image: '/images/white/products/p-192510012-grey.jpg', gallery: ['/images/white/products/p-192510012-grey-b.jpg', '/images/white/products/p-192510012-grey-d.jpg', '/images/white/products/p-192510012-grey-s.jpg', '/images/white/products/p-192510012-grey-m.jpg']}], image: '/images/white/products/p-192510012.jpg', nm: 192510012, gallery: ['/images/white/products/p-192510012-2.jpg', '/images/white/products/p-192510012-3.jpg', '/images/white/products/p-192510012-4.jpg', '/images/white/products/p-192510012-5.jpg', '/images/white/products/p-192510012-6.jpg', '/images/white/products/p-192510012-7.jpg']},
  {key: 13, slug: 'palto-v-polosku-s-poyasom', en: 'Striped Belted Coat', ru: 'Пальто в полоску с поясом', cat: 'outerwear', price: 34900, descEn: 'A long oversized coat in a fine tonal stripe, closed with a belt. A light layer over anything.', descRu: 'Длинное оверсайз-пальто в тонкую тональную полоску, на поясе. Лёгкий слой поверх чего угодно.', storyEn: 'A long oversized coat in a fine tonal stripe — the pattern reads up close and dissolves at a distance, leaving a sense of texture behind. The cut is loose, the shoulder dropped, the belt there to gather the waist when you want it. It falls below the knee. The wool blend is dense, holds its shape and does not collapse at the shoulder. Lined, with deep pockets. The stripe gives the coat character without arguing with what is underneath: jeans, a suit or a long dress all go under it.', storyRu: 'Длинное пальто оверсайз в тонкую тональную полоску — рисунок читается вблизи и растворяется на расстоянии, оставляя ощущение фактуры. Крой свободный, плечо приспущено, пояс собирает талию по желанию. Длина ниже колена. Шерстяная смесь плотная, держит форму и не садится в плечах. На подкладе, с глубокими карманами. Полоска даёт пальто характер, но не спорит с одеждой под ним: под него одинаково уходят джинсы, костюм и длинное платье.', compositionEn: 'Wool blend', compositionRu: 'Шерстяная смесь', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [SAND, {...CHARCOAL, image: '/images/white/products/p-814720607-charcoal.jpg', gallery: ['/images/white/products/p-814720607-charcoal-b.jpg', '/images/white/products/p-814720607-charcoal-d.jpg', '/images/white/products/p-814720607-charcoal-s.jpg', '/images/white/products/p-814720607-charcoal-m.jpg']}], image: '/images/white/products/p-814720607.jpg', nm: 814720607, gallery: ['/images/white/products/p-814720607-2.jpg', '/images/white/products/p-814720607-4.jpg', '/images/white/products/p-814720607-b.jpg', '/images/white/products/p-814720607-d.jpg']},
  {key: 14, slug: 'palto-kimono-vesennee', en: 'Spring Kimono Coat', ru: 'Пальто кимоно весеннее', cat: 'outerwear', price: 34900, descEn: 'A short kimono-cut coat for spring — wide sleeves, a wrap front, no fuss. Light layering.', descRu: 'Короткое пальто кроя кимоно для весны — широкий рукав, запа́х, без суеты. Лёгкий слой.', storyEn: 'A short kimono-cut coat for spring: a wide sleeve, a wrap front with no fastening, a straight shoulder line. No buttons, no zip — it holds on the wrap and the belt and goes on in one motion over anything. Hip length. The wool blend is light, made for +10 to +18: it keeps the wind off without overheating. The open armhole leaves room for a sweater. An in-between layer that looks composed even over house knitwear.', storyRu: 'Короткое пальто кроя кимоно на весну: широкий рукав, запáх без застёжки, прямая линия плеча. Никаких пуговиц и молний — пальто держится запахом и поясом, надевается одним движением поверх чего угодно. Длина до бедра. Шерстяная смесь лёгкая, рассчитанная на +10…+18: она защищает от ветра, но не перегревает. Свободная пройма позволяет надеть под него свитер. Это верхний слой для межсезонья, который выглядит собранным даже поверх домашнего трикотажа.', compositionEn: 'Wool blend', compositionRu: 'Шерстяная смесь', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [SAND], image: '/images/white/products/p-801438197.jpg', nm: 801438197, gallery: ['/images/white/products/p-801438197-2.jpg', '/images/white/products/p-801438197-3.jpg', '/images/white/products/p-801438197-b.jpg', '/images/white/products/p-801438197-d.jpg']},
  {key: 15, slug: 'palto-kimono-drapovoe', en: 'Draped Kimono Coat', ru: 'Пальто кимоно драповое', cat: 'outerwear', price: 34900, descEn: 'A draped wool kimono coat with a belt and a fluid fall. Heavy wool holds the shape; the silhouette moves with you.', descRu: 'Драповое пальто кимоно с поясом и текучим силуэтом. Плотный драп держит форму, силуэт двигается вместе с вами.', storyEn: 'A draped wool kimono coat with a belt: a wide sleeve, a soft shoulder, a fluid line with no hard edges. The wool is heavy and holds its shape by the weight of the cloth rather than by internal structure, so it settles on the body and falls straight. The belt ties loosely; the length sits below the knee. Warm enough for a real autumn and a mild winter. The kimono cut leaves the shoulders free — an oversized sweater goes underneath without breaking the line.', storyRu: 'Драповое пальто кимоно с поясом: широкий рукав, мягкое плечо, текучий силуэт без жёстких линий. Драп плотный и тяжёлый — он держит форму весом ткани, а не подкладными деталями, поэтому пальто садится по фигуре и падает ровно. Пояс завязывается свободно, длина ниже колена. Тепло для настоящей осени и мягкой зимы. Крой кимоно даёт свободу в плечах: под пальто уходит объёмный свитер, и силуэт не ломается.', compositionEn: 'Drape wool', compositionRu: 'Драп', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [CAMEL, {...CHARCOAL, image: '/images/white/products/p-795627344-charcoal.jpg', gallery: ['/images/white/products/p-795627344-charcoal-b.jpg', '/images/white/products/p-795627344-charcoal-d.jpg', '/images/white/products/p-795627344-charcoal-s.jpg', '/images/white/products/p-795627344-charcoal-m.jpg']}], image: '/images/white/products/p-795627344.jpg', nm: 795627344, gallery: ['/images/white/products/p-795627344-2.jpg', '/images/white/products/p-795627344-3.jpg', '/images/white/products/p-795627344-b.jpg', '/images/white/products/p-795627344-d.jpg']},
  {key: 16, slug: 'palto-kimono-korotkoe', en: 'Short Kimono Coat', ru: 'Пальто кимоно короткое', cat: 'outerwear', price: 34900, descEn: 'A cropped kimono coat with clean lines and a soft shoulder. A light top layer with no bulk.', descRu: 'Укороченное пальто кимоно с чистыми линиями и мягким плечом. Лёгкий верхний слой без объёма.', storyEn: 'A cropped kimono coat with clean lines and a soft shoulder. The cut is minimal: a wide armhole, a straight line, a wrap front with no fastening. Hip length — it ends where a skirt or trousers begin and does not cut the figure in half. A mid-weight wool blend for a cool summer and early autumn. This is the finishing layer to an outfit rather than protection from cold: it gives structure to a light dress and gathers a loose bottom half.', storyRu: 'Укороченное пальто кимоно с чистыми линиями и мягким плечом. Крой минимальный: широкая пройма, прямой силуэт, запáх без застёжки. Длина до бедра — пальто заканчивается там, где начинается юбка или брюки, и не перерезает фигуру. Шерстяная смесь средней плотности, для прохладного лета и ранней осени. Это завершающий слой к образу, а не защита от холода: он добавляет структуру лёгкому платью и собирает свободный низ.', compositionEn: 'Wool blend', compositionRu: 'Шерстяная смесь', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [SAND], image: '/images/white/products/p-795657866.jpg', nm: 795657866, gallery: ['/images/white/products/p-795657866-b.jpg', '/images/white/products/p-795657866-d.jpg']},
  {key: 17, slug: 'plate-vechernee', en: 'Evening Dress', ru: 'Платье вечернее', cat: 'dresses', price: 1375, descEn: 'An occasion dress cut close and clean. A clean neckline, a defined waist, made for evening.', descRu: 'Вечернее платье приталенного, сдержанного кроя. Чистая линия выреза, чёткая талия — для вечера.', storyEn: 'An occasion dress where everything rests on the fit. The bodice sits close, the waist is marked, the skirt runs straight down without extra volume. The neckline is clean and undecorated — jewellery reads better on it than any embroidery would. The crepe is dense and matte: it does not go sheer and does not cling to tights. Midi length. It covers most occasions — dinner, theatre, a wedding as a guest. It disappears under a coat, and a jacket over the shoulders turns it into an evening suit.', storyRu: 'Вечернее платье приталенного кроя, где всё решает посадка. Лиф садится по фигуре, талия обозначена, юбка идёт ровно вниз без лишнего объёма. Вырез чистый, без отделки — украшения читаются на нём лучше, чем на любой вышивке. Креп плотный, матовый, не просвечивает и не липнет к колготкам. Длина миди. Платье закрывает большинство поводов: ужин, театр, свадьба гостем. Под пальто уходит целиком, а с жакетом на плечах превращается в вечерний костюм.', compositionEn: 'Crepe', compositionRu: 'Креп', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [BLACK, {...BORDEAUX, image: '/images/white/products/p-192521903-bordeaux.jpg', gallery: ['/images/white/products/p-192521903-bordeaux-b.jpg', '/images/white/products/p-192521903-bordeaux-d.jpg', '/images/white/products/p-192521903-bordeaux-s.jpg', '/images/white/products/p-192521903-bordeaux-m.jpg']}], image: '/images/white/products/p-192521903.jpg', nm: 192521903, gallery: ['/images/white/products/p-192521903-2.jpg', '/images/white/products/p-192521903-d.jpg', '/images/white/products/p-192521903-b.jpg', '/images/white/products/p-192521903-s.jpg']},
  {key: 18, slug: 'zhilet-s-baskoy-i-kruzhevom', en: 'Lace Peplum Vest', ru: 'Жилет с баской и кружевом', cat: 'tailoring', price: 33400, descEn: 'A tailored peplum vest finished with lace. The sharpness of tailoring, softened at the edge.', descRu: 'Костюмный жилет с баской, завершённый кружевом. Острота тайлоринга, смягчённая по краю.', storyEn: 'A tailored peplum vest finished with lace along the bottom edge. The cut is strict: a structured shoulder, a V-neckline, a four-button front, a waist drawn in with darts. The peplum spreads softly and covers the hip. Scalloped lace runs along the very hem and takes the office dryness out of it — the piece reads as evening while staying tailored in cut. A dense wool blend that holds the shoulder line. Wear it with straight trousers as a suit, with jeans as a contrast, and over a fine roll-neck in winter.', storyRu: 'Костюмный жилет с баской, завершённый кружевом по нижнему краю. Крой строгий: структурное плечо, V-образный вырез, застёжка на четыре пуговицы, талия собрана вытачками. Баска расходится мягко и прикрывает бедро. Кружево с фестонами идёт по самому низу и снимает с жилета офисную сухость — вещь читается вечерней, оставаясь по крою деловой. Шерстяная смесь плотная, держит линию плеча. Носится с прямыми брюками как костюм, с джинсами как контраст и поверх тонкой водолазки зимой.', compositionEn: 'Wool blend with lace', compositionRu: 'Шерстяная смесь с кружевом', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [IVORY, {...BROWN, image: '/images/white/products/p-1224761706-v5-brown.jpg', gallery: ['/images/white/products/p-1224761706-v5-brown-b.jpg', '/images/white/products/p-1224761706-v5-brown-d.jpg', '/images/white/products/p-1224761706-v5-brown-s.jpg', '/images/white/products/p-1224761706-v5-brown-m.jpg']}, {...GREY, image: '/images/white/products/p-1224761706-v5-grey.jpg', gallery: ['/images/white/products/p-1224761706-v5-grey-b.jpg', '/images/white/products/p-1224761706-v5-grey-d.jpg', '/images/white/products/p-1224761706-v5-grey-s.jpg', '/images/white/products/p-1224761706-v5-grey-m.jpg']}, {...BLACK, image: '/images/white/products/p-1224761706-v5-black.jpg', gallery: ['/images/white/products/p-1224761706-v5-black-b.jpg', '/images/white/products/p-1224761706-v5-black-d.jpg', '/images/white/products/p-1224761706-v5-black-s.jpg', '/images/white/products/p-1224761706-v5-black-m.jpg']}], image: '/images/white/products/p-1224761706-v5.jpg', nm: 1224761706, gallery: ['/images/white/products/p-1224761706-v5-b.jpg', '/images/white/products/p-1224761706-v5-d.jpg', '/images/white/products/p-1224761706-v5-s.jpg', '/images/white/products/p-1224761706-v5-m.jpg']},
  {key: 19, slug: 'bluzka-shkolnaya-s-volanami', en: 'School Ruffle Blouse', ru: 'Блузка школьная с воланами', cat: 'dresses', price: 3177, descEn: 'An oversized school blouse with soft ruffles — crisp cotton, a clean collar, easy volume. The uniform, without the stiffness.', descRu: 'Школьная оверсайз-блузка с мягкими воланами — свежий хлопок, чистый воротник, лёгкий объём. Школьная форма без строгости.', storyEn: 'A relaxed school blouse with soft ruffles. The cut is oversized: a dropped shoulder, a full sleeve, a clean stand collar. The ruffles run across the chest and around the sleeve, giving the blouse lightness without turning it into occasion wear. The cotton blend breathes, does not build static and survives frequent washing at 40°, which is what actually matters in a uniform. Tuck it into a skirt or trousers, or wear it loose under a pinafore. A uniform that does not look like one.', storyRu: 'Школьная блузка свободного кроя с мягкими воланами. Крой оверсайз: приспущенное плечо, объёмный рукав, чистый воротник-стойка. Воланы идут по линии груди и рукаву и дают блузке лёгкость, не превращая её в нарядную. Хлопковая смесь дышит, не электризуется и переносит частую стирку при 40°, что для школьной формы решает всё. Заправляется в юбку и брюки, носится навыпуск с сарафаном. Форма, которая не выглядит формой.', compositionEn: 'Cotton blend', compositionRu: 'Хлопковая смесь', careEn: 'Machine wash warm', careRu: 'Машинная стирка при 40°', colors: [BROWN, {...BLACK, image: '/images/white/products/p-1126294272-black.jpg', gallery: ['/images/white/products/p-1126294272-black-b.jpg', '/images/white/products/p-1126294272-black-d.jpg', '/images/white/products/p-1126294272-black-s.jpg', '/images/white/products/p-1126294272-black-m.jpg']}, {...IVORY, image: '/images/white/products/p-1126294272-ivory.jpg', gallery: ['/images/white/products/p-1126294272-ivory-b.jpg', '/images/white/products/p-1126294272-ivory-d.jpg', '/images/white/products/p-1126294272-ivory-s.jpg', '/images/white/products/p-1126294272-ivory-m.jpg']}], image: '/images/white/products/p-1126294272.jpg', nm: 1126294272, gallery: ['/images/white/products/p-1126294272-2.jpg', '/images/white/products/p-1126294272-d.jpg', '/images/white/products/p-1126294272-b.jpg', '/images/white/products/p-1126294272-s.jpg']},
  {key: 20, slug: 'kurtka-bomber-zamsha', en: 'Suede Bomber Jacket', ru: 'Куртка бомбер замша', cat: 'outerwear', price: 50000, season: 'aw26', descEn: 'A bomber in natural suede — a soft collar, an elastic hem, an easy shoulder. Autumn outerwear that asks nothing of you.', descRu: 'Бомбер из натуральной замши — мягкий воротник, резинка по низу, свободное плечо. Осенняя верхняя одежда, которая ничего не требует.', storyEn: 'A bomber cut from natural suede rather than a coating that imitates it — the nap is uneven in the light and the hide softens along the fold lines with wear instead of cracking. The shape is loose: a dropped shoulder, a full sleeve, a shirt collar that stands or falls as you leave it. A seam runs across the chest and the front closes with a concealed zip, so nothing interrupts the surface. Elastic gathers the hem and the cuffs, which is what gives the bomber its shape and keeps the wind out at the waist. Unlined and light for its warmth. It sits over a roll-neck through autumn and takes wide trousers and a straight skirt equally well.', storyRu: 'Бомбер скроен из натуральной замши, а не из покрытия, которое её имитирует: ворс неровно ложится на свету, а кожа по линиям сгиба со временем смягчается, вместо того чтобы трескаться. Силуэт свободный — приспущенное плечо, объёмный рукав, рубашечный воротник, который стоит или падает как оставите. По линии груди идёт шов, застёжка на скрытую молнию, поэтому поверхность ничем не разбита. Резинка собирает низ и манжеты — именно она держит форму бомбера и не пускает ветер по талии. Без подклада и лёгкий для своего тепла. Всю осень садится поверх водолазки, одинаково берёт широкие брюки и прямую юбку.', compositionEn: 'Natural suede', compositionRu: 'Натуральная замша', careEn: 'Dry clean only', careRu: 'Только химчистка', colors: [{...BROWN, image: '/images/white/products/p-1260050013-brown.jpg', gallery: ['/images/white/products/p-1260050013-brown-b.jpg', '/images/white/products/p-1260050013-brown-c.jpg', '/images/white/products/p-1260050013-brown-d.jpg']}, {...SAND, image: '/images/white/products/p-1260050014-sand.jpg', gallery: ['/images/white/products/p-1260050014-sand-b.jpg', '/images/white/products/p-1260050014-sand-c.jpg', '/images/white/products/p-1260050014-sand-d.jpg']}, {...GREEN, image: '/images/white/products/p-1260050015-green.jpg', gallery: ['/images/white/products/p-1260050015-green-b.jpg', '/images/white/products/p-1260050015-green-c.jpg', '/images/white/products/p-1260050015-green-d.jpg']}], image: '/images/white/products/p-1260050013-brown.jpg', nm: 1260050013, gallery: ['/images/white/products/p-1260050013-brown-b.jpg', '/images/white/products/p-1260050013-brown-c.jpg', '/images/white/products/p-1260050013-brown-d.jpg']},
];

// Editorial imagery — model-on-white shots generated for the White variant (the
// REINASLEO Soul), used for the hero, the atelier/lookbook block and as
// alternate PDP gallery views. Same-origin, so CSP img-src 'self' covers them.
export const WHITE_HERO_IMAGE = '/images/white/hero-mark2.jpg';
export const WHITE_ATELIER_IMAGE = '/images/white/editorial-1.jpg';
export const WHITE_EDITORIAL = ['/images/white/editorial-1.jpg', '/images/white/editorial-2.jpg', '/images/white/editorial-3.jpg'];

export function findWhiteProduct(key?: string | number | null): WhiteProduct | undefined {
  if (key == null) return undefined;
  const k = typeof key === 'string' ? Number.parseInt(key, 10) : key;
  if (Number.isNaN(k)) return undefined;
  return WHITE_PRODUCTS.find((p) => p.key === k);
}

export function findWhiteProductBySlug(slug?: string | null): WhiteProduct | undefined {
  if (!slug) return undefined;
  return WHITE_PRODUCTS.find((p) => p.slug === slug);
}

// Canonical product path. Everything that links to a garment goes through this
// so the slug never has to be assembled by hand at a call site.
export function whiteProductHref(locale: string, product: Pick<WhiteProduct, 'slug'>): string {
  return `/${locale}/product/${product.slug}`;
}

// Nothing here knows what is on the shelf. The catalogue is a static file and
// the real count lives at Wildberries, so the site cannot honestly offer a
// garment for its own bag — it would take an order it may not be able to fill.
// Until stock is wired up (the Ozon integration), every piece reads as
// unavailable and Wildberries is the one route to buying it.
//
// This is the single switch: give it a real source and the whole storefront —
// product page, quick add, markup — starts telling the truth at once.
export function whiteInStock(_product: Pick<WhiteProduct, 'key'>): boolean {
  return false;
}

// Pieces that have gone from the marketplaces too — sold out at Wildberries and
// not on Ozon. They keep their page (the photographs and the search listing are
// worth having) but there is nowhere to send a buyer, so the page offers to take
// a pre-order instead of pretending a route exists. Add a key here when the last
// one leaves the warehouse.
const WHITE_OFF_MARKETPLACES = new Set<number>([]);

// Three honest states, in the order the storefront checks them:
//   'site'        — we hold it and the bag can take it
//   'marketplace' — we do not, but Wildberries or Ozon does
//   'none'        — nowhere; the page offers a pre-order
// Everything that decides between a bag button, a marketplace button and a
// pre-order form reads this one function, so the three can never disagree.
export type WhiteAvailability = 'site' | 'marketplace' | 'none';

export function whiteAvailability(
  product: Pick<WhiteProduct, 'key' | 'nm'>,
  // `onWb` comes from the live marketplace snapshot; it defaults to true so a
  // caller without it keeps the old behaviour of trusting the article number.
  opts?: {onOzon?: boolean; onWb?: boolean},
): WhiteAvailability {
  if (whiteInStock(product)) return 'site';
  if (opts?.onOzon) return 'marketplace';
  const wb = opts?.onWb ?? true;
  if (wb && product.nm && !WHITE_OFF_MARKETPLACES.has(product.key)) return 'marketplace';
  return 'none';
}

export const WHITE_CATS: WhiteCat[] = ['dresses', 'outerwear', 'knitwear', 'tailoring', 'skirts'];

// Single source for the size run, shared by the PDP and the card Quick Add so
// they never drift. Demo sizing — real per-product runs arrive with the catalog.
export const WHITE_SIZES = ['XS', 'S', 'M', 'L', 'XL'] as const;
export type WhiteSize = (typeof WHITE_SIZES)[number];

// Validate a ?cat query value so the shop can be deep-linked/shared. Anything
// unrecognised collapses to 'all' (shared by server page + client showcase).
export function normalizeWhiteCat(value?: string | null): WhiteCat | 'all' {
  return value != null && (WHITE_CATS as string[]).includes(value) ? (value as WhiteCat) : 'all';
}

// Single source of category labels (en/ru), shared by the shop filter chips and
// the server-side <title>, so the two never drift. 'all' is contextual (chip
// reads "All", title reads "Shop"), so each caller supplies that label itself.
const WHITE_CAT_LABELS: Record<WhiteCat, [en: string, ru: string]> = {
  dresses: ['Dresses', 'Платья'],
  outerwear: ['Outerwear', 'Верхняя одежда'],
  knitwear: ['Knitwear', 'Трикотаж'],
  tailoring: ['Tailoring', 'Костюмы'],
  skirts: ['Skirts', 'Юбки'],
};
export function whiteCatLabel(cat: WhiteCat, locale: string): string {
  const [en, ru] = WHITE_CAT_LABELS[cat];
  return locale === 'ru' ? ru : en;
}

// Curated sets — looks assembled from the real catalogue, sold together or
// piece by piece. The image is the set's editorial mood; the items below it
// are the actual products (each with its own card and sizes).
export type WhiteSet = {
  key: string;
  en: string;
  ru: string;
  descEn: string;
  descRu: string;
  image: string;
  productKeys: number[];
  // Which colour of each garment is the one actually worn in the photograph,
  // keyed by product. Without it the cards fall back to a product's first
  // colour, so a look shot in a brown coat and a sand skirt was listed as a
  // black coat and a black skirt — the same two garments, but not this outfit.
  // Only needed where the set differs from the default; omit and the default
  // is right.
  colours?: Record<number, string>;
};

